// ==UserScript==
// @name         Monitor
// @namespace    local.runtime.monitor
// @version      1.4.2
// @description  Monitor fetch/XHR responses, Web Storage and window globals in a bounded in-page dashboard.
// @author       You
// @match        *://*/*
// @match        file:///*
// @run-at       document-start
// @grant        none
// ==/UserScript==

(function runtimeMonitor() {
  'use strict';

  const MARK = Symbol.for('runtime-monitor.hooked');
  if (window.fetch && window.fetch[MARK]) return;
  const VERSION = '1.4.2';
  const ICON_DATA_URL = 'data:image/png;base64,';

  const DEFAULTS = Object.freeze({
    maxNetworkEntries: 200,
    maxResponseBytes: 256 * 1024,
    maxNetworkTextBytes: 5 * 1024 * 1024,
    maxConcurrentFetchCaptures: 8,
    maxStorageValueChars: 16 * 1024,
    maxGlobalPreviewChars: 1200,
    maxGlobalSearchChars: 16 * 1024,
    maxGlobalSearchTotalChars: 2 * 1024 * 1024,
    maxGlobalSearchDepth: 5,
    maxGlobalSearchNodes: 300,
    maxGlobalSearchKeysPerObject: 100,
    maxTimelineEntries: 500,
    scanIntervalMs: 1000,
    maxGlobalKeys: 10000,
    globalFingerprintKeys: 30,
  });

  const config = { ...DEFAULTS };
  const state = {
    paused: false,
    sequence: 0,
    network: [],
    networkTextBytes: 0,
    storage: new Map(),
    globals: new Map(),
    globalSearchChars: 0,
    timeline: [],
    selected: null,
    activeTab: 'network',
    filter: '',
    showGlobalFunctions: false,
    showInitialGlobals: false,
    uiReady: false,
    renderQueued: false,
  };
  let activeFetchCaptures = 0;

  const original = {
    fetch: typeof window.fetch === 'function' ? window.fetch : null,
    xhrOpen: XMLHttpRequest.prototype.open,
    xhrSend: XMLHttpRequest.prototype.send,
    storageSetItem: Storage.prototype.setItem,
    storageRemoveItem: Storage.prototype.removeItem,
    storageClear: Storage.prototype.clear,
  };

  const xhrMetadata = new WeakMap();

  function nowIso() {
    return new Date().toISOString();
  }

  function safeString(value, maxChars = 1000) {
    try {
      if (typeof value === 'string') return truncate(value, maxChars);
      if (typeof value === 'undefined') return 'undefined';
      if (typeof value === 'function') return `[Function ${value.name || 'anonymous'}]`;
      if (typeof value === 'symbol') return value.toString();
      if (typeof value === 'bigint') return `${value}n`;
      const seen = new WeakSet();
      const json = JSON.stringify(value, (_key, item) => {
        if (typeof item === 'bigint') return `${item}n`;
        if (typeof item === 'function') return `[Function ${item.name || 'anonymous'}]`;
        if (typeof item === 'symbol') return item.toString();
        if (item && typeof item === 'object') {
          if (seen.has(item)) return '[Circular]';
          seen.add(item);
        }
        return item;
      });
      return truncate(json === undefined ? String(value) : json, maxChars);
    } catch (error) {
      return `[Unserializable: ${error && error.message ? error.message : String(error)}]`;
    }
  }

  function truncate(text, maxChars) {
    const value = String(text);
    if (value.length <= maxChars) return value;
    return `${value.slice(0, maxChars)}\n… [truncated ${value.length - maxChars} chars]`;
  }

  function roughBytes(text) {
    return typeof text === 'string' ? text.length * 2 : 0;
  }

  function addTimeline(source, action, key, detail = '') {
    if (state.paused) return;
    state.timeline.unshift({
      id: ++state.sequence,
      source,
      action,
      key: String(key),
      detail: truncate(detail, 500),
      time: nowIso(),
    });
    if (state.timeline.length > config.maxTimelineEntries) {
      state.timeline.length = config.maxTimelineEntries;
    }
    scheduleRender();
  }

  function enforceNetworkLimits() {
    while (
      state.network.length > config.maxNetworkEntries ||
      state.networkTextBytes > config.maxNetworkTextBytes
    ) {
      const removed = state.network.pop();
      if (!removed) break;
      state.networkTextBytes -= roughBytes(removed.responseBody) + roughBytes(removed.requestBody);
    }
    state.networkTextBytes = Math.max(0, state.networkTextBytes);
  }

  function addNetwork(entry) {
    if (state.paused) return null;
    const normalized = {
      id: ++state.sequence,
      time: nowIso(),
      type: entry.type,
      method: entry.method || 'GET',
      url: String(entry.url || ''),
      status: Number(entry.status) || 0,
      ok: Boolean(entry.ok),
      durationMs: Math.round(Number(entry.durationMs) || 0),
      contentType: String(entry.contentType || ''),
      requestBody: truncate(entry.requestBody || '', 4096),
      responseBody: truncate(entry.responseBody || '', config.maxResponseBytes),
      responseBytes: Number(entry.responseBytes) || 0,
      truncated: Boolean(entry.truncated),
      error: entry.error ? String(entry.error) : '',
    };
    state.network.unshift(normalized);
    state.networkTextBytes += roughBytes(normalized.responseBody) + roughBytes(normalized.requestBody);
    enforceNetworkLimits();
    addTimeline('network', normalized.error ? 'error' : 'response', normalized.url,
      `${normalized.method} ${normalized.status} ${normalized.durationMs}ms`);
    return normalized.id;
  }

  function updateNetwork(id, patch) {
    const entry = state.network.find((item) => item.id === id);
    if (!entry) return false;
    state.networkTextBytes -= roughBytes(entry.responseBody) + roughBytes(entry.requestBody);
    if ('responseBody' in patch) entry.responseBody = truncate(patch.responseBody || '', config.maxResponseBytes);
    if ('requestBody' in patch) entry.requestBody = truncate(patch.requestBody || '', 4096);
    if ('responseBytes' in patch) entry.responseBytes = Number(patch.responseBytes) || 0;
    if ('truncated' in patch) entry.truncated = Boolean(patch.truncated);
    if ('error' in patch) entry.error = patch.error ? String(patch.error) : '';
    if ('contentType' in patch) entry.contentType = String(patch.contentType || '');
    state.networkTextBytes += roughBytes(entry.responseBody) + roughBytes(entry.requestBody);
    enforceNetworkLimits();
    scheduleRender();
    return true;
  }

  function isTextualResponse(contentType) {
    if (!contentType) return true;
    return /(^text\/)|json|javascript|xml|html|x-www-form-urlencoded|graphql|svg/i.test(contentType);
  }

  async function readFetchBodyLimited(response) {
    const contentType = response.headers.get('content-type') || '';
    const declaredLength = Number(response.headers.get('content-length'));
    if (!isTextualResponse(contentType)) {
      return { text: `[body omitted: ${contentType || 'binary'}]`, bytes: 0, truncated: false };
    }
    if (Number.isFinite(declaredLength) && declaredLength > config.maxResponseBytes) {
      return {
        text: `[body omitted: content-length ${declaredLength} exceeds ${config.maxResponseBytes} byte limit]`,
        bytes: declaredLength,
        truncated: true,
      };
    }

    const clone = response.clone();
    if (!clone.body || typeof clone.body.getReader !== 'function') {
      return { text: '[body omitted: streaming reader unavailable]', bytes: 0, truncated: false };
    }

    const reader = clone.body.getReader();
    const decoder = new TextDecoder();
    let text = '';
    let bytes = 0;
    let truncatedBody = false;
    try {
      while (true) {
        const part = await reader.read();
        if (part.done) break;
        if (!part.value) continue;
        const remaining = config.maxResponseBytes - bytes;
        if (part.value.byteLength > remaining) {
          if (remaining > 0) text += decoder.decode(part.value.subarray(0, remaining), { stream: true });
          bytes += part.value.byteLength;
          truncatedBody = true;
          await reader.cancel('Monitor response limit reached').catch(() => {});
          break;
        }
        bytes += part.value.byteLength;
        text += decoder.decode(part.value, { stream: true });
      }
      text += decoder.decode();
      return { text, bytes, truncated: truncatedBody };
    } finally {
      reader.releaseLock();
    }
  }

  function installFetchHook() {
    if (!original.fetch) return;
    async function monitoredFetch(...args) {
      const started = performance.now();
      const input = args[0];
      const init = args[1] || {};
      const url = typeof input === 'string' || input instanceof URL ? String(input) : input && input.url;
      const method = String(init.method || (input && input.method) || 'GET').toUpperCase();
      const requestBody = typeof init.body === 'string' ? truncate(init.body, 4096) : '';
      try {
        const response = await original.fetch.apply(this, args);
        if (!state.paused) {
          if (activeFetchCaptures >= config.maxConcurrentFetchCaptures) {
            addNetwork({
              type: 'fetch', method, url, status: response.status, ok: response.ok,
              durationMs: performance.now() - started,
              contentType: response.headers.get('content-type') || '', requestBody,
              responseBody: `[body omitted: more than ${config.maxConcurrentFetchCaptures} concurrent captures]`,
            });
          } else {
            activeFetchCaptures += 1;
            const networkId = addNetwork({
              type: 'fetch', method, url, status: response.status, ok: response.ok,
              durationMs: performance.now() - started,
              contentType: response.headers.get('content-type') || '', requestBody,
              responseBody: '[capturing response body…]',
            });
            readFetchBodyLimited(response).then((body) => {
              updateNetwork(networkId, {
                responseBody: body.text, responseBytes: body.bytes, truncated: body.truncated,
              });
            }).catch((error) => {
              updateNetwork(networkId, {
                responseBody: '[response capture failed]', error: error.message || String(error),
              });
            }).finally(() => { activeFetchCaptures -= 1; });
          }
        }
        return response;
      } catch (error) {
        addNetwork({ type: 'fetch', method, url, durationMs: performance.now() - started,
          requestBody, error: error.message || String(error) });
        throw error;
      }
    }
    Object.defineProperty(monitoredFetch, MARK, { value: true });
    try { Object.defineProperty(monitoredFetch, 'name', { value: 'fetch' }); } catch (_) {}
    window.fetch = monitoredFetch;
  }

  function xhrBodyPreview(xhr) {
    try {
      if (xhr.responseType === '' || xhr.responseType === 'text') {
        const text = xhr.responseText || '';
        return {
          text: truncate(text, config.maxResponseBytes),
          bytes: roughBytes(text),
          truncated: text.length > config.maxResponseBytes,
        };
      }
      if (xhr.responseType === 'json') {
        const text = safeString(xhr.response, config.maxResponseBytes);
        return { text, bytes: roughBytes(text), truncated: text.length >= config.maxResponseBytes };
      }
      const size = xhr.response && (xhr.response.byteLength || xhr.response.size);
      return { text: `[body omitted: responseType=${xhr.responseType}${size ? `, ${size} bytes` : ''}]`, bytes: size || 0, truncated: false };
    } catch (error) {
      return { text: `[body unavailable: ${error.message || error}]`, bytes: 0, truncated: false };
    }
  }

  function installXhrHook() {
    if (original.xhrOpen[MARK]) return;
    function monitoredOpen(method, url, ...rest) {
      xhrMetadata.set(this, { method: String(method || 'GET').toUpperCase(), url: String(url || '') });
      return original.xhrOpen.call(this, method, url, ...rest);
    }
    function monitoredSend(body) {
      const xhr = this;
      const meta = xhrMetadata.get(xhr) || { method: 'GET', url: '' };
      meta.started = performance.now();
      meta.requestBody = typeof body === 'string' ? truncate(body, 4096) : '';
      const onDone = () => {
        xhr.removeEventListener('loadend', onDone);
        xhrMetadata.delete(xhr);
        if (state.paused) return;
        const response = xhrBodyPreview(xhr);
        addNetwork({
          type: 'xhr', method: meta.method, url: meta.url, status: xhr.status,
          ok: xhr.status >= 200 && xhr.status < 400,
          durationMs: performance.now() - meta.started,
          contentType: xhr.getResponseHeader('content-type') || '',
          requestBody: meta.requestBody, responseBody: response.text,
          responseBytes: response.bytes, truncated: response.truncated,
        });
      };
      xhr.addEventListener('loadend', onDone);
      return original.xhrSend.call(xhr, body);
    }
    Object.defineProperty(monitoredOpen, MARK, { value: true });
    XMLHttpRequest.prototype.open = monitoredOpen;
    XMLHttpRequest.prototype.send = monitoredSend;
  }

  function storageKind(storage) {
    try {
      if (storage === window.localStorage) return 'localStorage';
      if (storage === window.sessionStorage) return 'sessionStorage';
    } catch (_) {}
    return 'storage';
  }

  function storageMapKey(kind, key) {
    return `${kind}\u0000${key}`;
  }

  function storageItemId(kind, key) {
    return `${kind}:${encodeURIComponent(String(key))}`;
  }

  function recordStorage(kind, key, value, action, previousValue) {
    if (state.paused) return;
    const mapKey = storageMapKey(kind, key);
    if (action === 'delete') {
      state.storage.delete(mapKey);
    } else if (action === 'clear') {
      for (const existingKey of [...state.storage.keys()]) {
        if (existingKey.startsWith(`${kind}\u0000`)) state.storage.delete(existingKey);
      }
    } else {
      state.storage.set(mapKey, {
        id: storageItemId(kind, key), kind, key: String(key),
        value: truncate(value == null ? '' : value, config.maxStorageValueChars),
        fullLength: value == null ? 0 : String(value).length,
        updatedAt: nowIso(),
      });
    }
    addTimeline('storage', action, `${kind}.${key}`, previousValue == null ? '' : `previous: ${truncate(previousValue, 200)}`);
    scheduleRender();
  }

  function installStorageHook() {
    function monitoredSetItem(key, value) {
      const kind = storageKind(this);
      let previous = null;
      try { previous = this.getItem(key); } catch (_) {}
      const result = original.storageSetItem.call(this, key, value);
      recordStorage(kind, key, String(value), previous === null ? 'add' : 'update', previous);
      return result;
    }
    function monitoredRemoveItem(key) {
      const kind = storageKind(this);
      let previous = null;
      try { previous = this.getItem(key); } catch (_) {}
      const result = original.storageRemoveItem.call(this, key);
      recordStorage(kind, key, null, 'delete', previous);
      return result;
    }
    function monitoredClear() {
      const kind = storageKind(this);
      const result = original.storageClear.call(this);
      recordStorage(kind, '*', null, 'clear', null);
      return result;
    }
    Object.defineProperty(monitoredSetItem, MARK, { value: true });
    Storage.prototype.setItem = monitoredSetItem;
    Storage.prototype.removeItem = monitoredRemoveItem;
    Storage.prototype.clear = monitoredClear;

    window.addEventListener('storage', (event) => {
      const kind = event.storageArea === localStorage ? 'localStorage' : 'sessionStorage';
      if (event.key === null) recordStorage(kind, '*', null, 'clear', event.oldValue);
      else recordStorage(kind, event.key, event.newValue, event.newValue === null ? 'delete' : 'update', event.oldValue);
    });
  }

  function scanStorage(initial = false) {
    for (const [kind, storage] of [['localStorage', safeStorage('localStorage')], ['sessionStorage', safeStorage('sessionStorage')]]) {
      if (!storage) continue;
      const found = new Set();
      try {
        for (let index = 0; index < storage.length; index += 1) {
          const key = storage.key(index);
          if (key == null) continue;
          found.add(storageMapKey(kind, key));
          const value = storage.getItem(key) || '';
          const existing = state.storage.get(storageMapKey(kind, key));
          const preview = truncate(value, config.maxStorageValueChars);
          if (!existing) {
            state.storage.set(storageMapKey(kind, key), { id: storageItemId(kind, key), kind, key, value: preview, fullLength: value.length, updatedAt: nowIso() });
            if (!initial) addTimeline('storage', 'add', `${kind}.${key}`, 'detected by scan');
          } else if (existing.value !== preview || existing.fullLength !== value.length) {
            recordStorage(kind, key, value, 'update', existing.value);
          }
        }
        for (const mapKey of [...state.storage.keys()]) {
          if (mapKey.startsWith(`${kind}\u0000`) && !found.has(mapKey)) {
            const existing = state.storage.get(mapKey);
            state.storage.delete(mapKey);
            if (!initial) addTimeline('storage', 'delete', `${kind}.${existing.key}`, 'detected by scan');
          }
        }
      } catch (_) {}
    }
  }

  function safeStorage(name) {
    try { return window[name]; } catch (_) { return null; }
  }

  function globalFingerprint(key) {
    try {
      const descriptor = Object.getOwnPropertyDescriptor(window, key);
      if (!descriptor) return { fingerprint: '[missing]', preview: '[missing]', type: 'missing' };
      if (!('value' in descriptor)) {
        return { fingerprint: '[accessor]', preview: '[Getter/Setter]', type: 'accessor' };
      }
      const value = descriptor.value;
      const type = value === null ? 'null' : typeof value;
      if ((type !== 'object' && type !== 'function') || value === null) {
        const preview = safeString(value, config.maxGlobalPreviewChars);
        return { fingerprint: `${type}:${preview}`, preview, type };
      }
      let keys = [];
      try { keys = Reflect.ownKeys(value).slice(0, config.globalFingerprintKeys); } catch (_) {}
      const shallow = [];
      for (const childKey of keys) {
        try {
          const childDescriptor = Object.getOwnPropertyDescriptor(value, childKey);
          if (!childDescriptor || !('value' in childDescriptor)) continue;
          const child = childDescriptor.value;
          if (child === null || !['object', 'function'].includes(typeof child)) {
            shallow.push(`${String(childKey)}=${safeString(child, 100)}`);
          } else {
            shallow.push(`${String(childKey)}=[${Array.isArray(child) ? 'Array' : typeof child}]`);
          }
        } catch (_) {}
      }
      const ctor = Array.isArray(value) ? 'Array' : type === 'function' ? 'Function' : 'Object';
      const preview = `${ctor} { ${shallow.join(', ')}${keys.length >= config.globalFingerprintKeys ? ', …' : ''} }`;
      return {
        fingerprint: truncate(`${ctor}|${keys.map(String).join('|')}|${shallow.join('|')}`, config.maxGlobalPreviewChars),
        preview: truncate(preview, config.maxGlobalPreviewChars),
        type: ctor,
      };
    } catch (error) {
      const preview = `[Unreadable: ${error.message || error}]`;
      return { fingerprint: preview, preview, type: 'unknown' };
    }
  }

  function shouldIndexInitialGlobal(key) {
    try {
      const descriptor = Object.getOwnPropertyDescriptor(window, key);
      if (!descriptor || !('value' in descriptor) || !descriptor.value || typeof descriptor.value !== 'object') return false;
      if (Array.isArray(descriptor.value)) return true;
      const prototype = Object.getPrototypeOf(descriptor.value);
      return prototype === Object.prototype || prototype === null;
    } catch (_) {
      return false;
    }
  }

  function buildGlobalSearchText(key) {
    try {
      const descriptor = Object.getOwnPropertyDescriptor(window, key);
      if (!descriptor || !('value' in descriptor)) return '';
      const root = descriptor.value;
      if (!root || typeof root !== 'object') return '';

      const parts = [];
      const seen = new WeakSet();
      const queue = [{ value: root, path: String(key), depth: 0 }];
      let chars = 0;
      let nodes = 0;
      const append = (text) => {
        if (chars >= config.maxGlobalSearchChars) return;
        const remaining = config.maxGlobalSearchChars - chars;
        const chunk = String(text).slice(0, remaining);
        if (!chunk) return;
        parts.push(chunk);
        chars += chunk.length + 1;
      };

      while (queue.length && nodes < config.maxGlobalSearchNodes && chars < config.maxGlobalSearchChars) {
        const current = queue.shift();
        const value = current.value;
        const valueType = value === null ? 'null' : typeof value;
        nodes += 1;

        if (value === null || !['object', 'function'].includes(valueType)) {
          append(`${current.path} ${safeString(value, config.maxGlobalSearchChars - chars)}`);
          continue;
        }
        if (valueType === 'function') {
          append(`${current.path} [Function ${value.name || 'anonymous'}]`);
          continue;
        }
        if (seen.has(value)) {
          append(`${current.path} [Circular]`);
          continue;
        }
        seen.add(value);
        append(`${current.path} [${Array.isArray(value) ? 'Array' : 'Object'}]`);
        if (current.depth >= config.maxGlobalSearchDepth) continue;

        let childKeys = [];
        try { childKeys = Reflect.ownKeys(value).slice(0, config.maxGlobalSearchKeysPerObject); } catch (_) {}
        for (const childKey of childKeys) {
          if (queue.length + nodes >= config.maxGlobalSearchNodes) break;
          const childPath = `${current.path}.${String(childKey)}`;
          try {
            const childDescriptor = Object.getOwnPropertyDescriptor(value, childKey);
            if (!childDescriptor) continue;
            if (!('value' in childDescriptor)) {
              append(`${childPath} [Getter/Setter skipped]`);
              continue;
            }
            queue.push({ value: childDescriptor.value, path: childPath, depth: current.depth + 1 });
          } catch (_) {
            append(`${childPath} [Unreadable]`);
          }
        }
      }
      return parts.join('\n');
    } catch (_) {
      return '';
    }
  }

  function replaceGlobalEntry(key, info, initial, searchText) {
    const existing = state.globals.get(key);
    if (existing && existing.searchText) state.globalSearchChars -= existing.searchText.length;
    const entry = {
      id: String(key), key: String(key), ...info, searchText,
      searchEvicted: existing ? Boolean(existing.searchEvicted) : false,
      updatedAt: nowIso(), initial,
    };
    state.globals.set(key, entry);
    state.globalSearchChars += searchText.length;

    for (const [candidateKey, candidate] of state.globals) {
      if (state.globalSearchChars <= config.maxGlobalSearchTotalChars) break;
      if (candidateKey === key || !candidate.searchText) continue;
      state.globalSearchChars -= candidate.searchText.length;
      candidate.searchText = '';
      candidate.searchEvicted = true;
    }
    state.globalSearchChars = Math.max(0, state.globalSearchChars);
    return entry;
  }

  function scanGlobals(initial = false) {
    let keys;
    try { keys = Reflect.ownKeys(window).slice(0, config.maxGlobalKeys); } catch (_) { return; }
    const found = new Set(keys);
    for (const key of keys) {
      const info = globalFingerprint(key);
      const existing = state.globals.get(key);
      const isInitialEntry = existing ? existing.initial : initial;
      const canDeepIndex = ['Object', 'Array'].includes(info.type)
        && (!isInitialEntry || shouldIndexInitialGlobal(key))
        && !(existing && existing.searchEvicted);
      const searchText = canDeepIndex ? buildGlobalSearchText(key) : '';
      if (!existing) {
        replaceGlobalEntry(key, info, initial, searchText);
        if (!initial) addTimeline('globals', 'add', String(key), info.preview);
      } else if (existing.fingerprint !== info.fingerprint || existing.searchText !== searchText) {
        replaceGlobalEntry(key, info, false, searchText);
        if (!initial) addTimeline('globals', 'update', String(key), `${existing.preview} → ${info.preview}`);
      }
    }
    for (const key of [...state.globals.keys()]) {
      if (!found.has(key)) {
        const previous = state.globals.get(key);
        if (previous.searchText) state.globalSearchChars -= previous.searchText.length;
        state.globals.delete(key);
        if (!initial) addTimeline('globals', 'delete', String(key), previous.preview);
      }
    }
    scheduleRender();
  }

  function escapeHtml(value) {
    return String(value).replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
  }

  function highlightText(value) {
    const text = String(value);
    const query = state.filter.trim();
    if (!query) return escapeHtml(text);
    const lowerText = text.toLowerCase();
    const lowerQuery = query.toLowerCase();
    let cursor = 0;
    let html = '';
    while (cursor < text.length) {
      const index = lowerText.indexOf(lowerQuery, cursor);
      if (index === -1) break;
      html += escapeHtml(text.slice(cursor, index));
      html += `<mark>${escapeHtml(text.slice(index, index + query.length))}</mark>`;
      cursor = index + query.length;
    }
    return html + escapeHtml(text.slice(cursor));
  }

  function matchingSnippet(item, fallback) {
    const query = state.filter.trim().toLowerCase();
    if (!query) return fallback;
    for (const [, candidate] of searchableFields(item)) {
      if (candidate == null) continue;
      const text = String(candidate).replace(/\s+/g, ' ');
      const index = text.toLowerCase().indexOf(query);
      if (index === -1) continue;
      const start = Math.max(0, index - 18);
      const end = Math.min(text.length, index + query.length + 60);
      return `${start ? '…' : ''}${text.slice(start, end)}${end < text.length ? '…' : ''}`;
    }
    return fallback;
  }

  function searchableFields(item) {
    if (state.activeTab === 'network') return [
      ['URL', item.url], ['响应内容', item.responseBody], ['请求内容', item.requestBody],
      ['Content-Type', item.contentType], ['错误', item.error],
    ];
    if (state.activeTab === 'storage') return [
      ['键名', item.key], ['Storage 值', item.value], ['存储类型', item.kind],
    ];
    if (state.activeTab === 'globals') return [
      ['变量名', item.key], ['变量预览', item.preview], ['嵌套对象索引', item.searchText], ['类型', item.type],
    ];
    return [['名称', item.key], ['变化内容', item.detail], ['来源', item.source], ['动作', item.action]];
  }

  function matchingDetails(item) {
    const query = state.filter.trim().toLowerCase();
    if (!query) return [];
    const matches = [];
    for (const [label, candidate] of searchableFields(item)) {
      if (candidate == null) continue;
      const text = String(candidate).replace(/\s+/g, ' ');
      const lowerText = text.toLowerCase();
      let cursor = 0;
      while (matches.length < 20) {
        const index = lowerText.indexOf(query, cursor);
        if (index === -1) break;
        const start = Math.max(0, index - 35);
        const end = Math.min(text.length, index + query.length + 90);
        matches.push({
          label,
          text: `${start ? '…' : ''}${text.slice(start, end)}${end < text.length ? '…' : ''}`,
        });
        cursor = index + query.length;
      }
      if (matches.length >= 20) break;
    }
    return matches;
  }

  let host;
  let shadow;
  function createUi() {
    if (state.uiReady || !document.documentElement) return;
    state.uiReady = true;
    host = document.createElement('div');
    host.style.cssText = 'all:initial;position:fixed;z-index:2147483647;right:16px;bottom:16px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace';
    shadow = host.attachShadow({ mode: 'open' });
    shadow.innerHTML = `
      <style>
        :host{color-scheme:dark}*{box-sizing:border-box}.panel{width:min(980px,calc(100vw - 32px));height:min(680px,calc(100vh - 32px));background:#0c111b;color:#d8e2f0;border:1px solid #293449;border-radius:14px;box-shadow:0 18px 60px #000a;display:none;overflow:hidden}.panel.open{display:grid;grid-template-rows:auto auto 1fr auto}.head{display:flex;align-items:center;gap:10px;padding:11px 13px;background:#121a28;border-bottom:1px solid #263249;cursor:move}.title{font-weight:800;color:#78d7ff;letter-spacing:.2px}.title small{opacity:.65;font-weight:600}.stats{font:11px system-ui;color:#93a4ba;flex:1}.controls{display:flex;gap:6px}.btn,input{border:1px solid #34425b;background:#172132;color:#d9e4f2;border-radius:7px;padding:6px 9px;font:12px system-ui}.btn{cursor:pointer}.btn:hover{background:#24334b}.tabs{display:flex;align-items:center;gap:4px;padding:8px 10px;border-bottom:1px solid #263249}.tab.active{background:#176b87;color:white}.search{margin-left:auto;width:220px}.body{display:grid;grid-template-columns:minmax(260px,38%) 1fr;min-height:0}.list{overflow:auto;border-right:1px solid #263249}.row{padding:9px 11px;border-bottom:1px solid #202a3d;cursor:pointer}.row:hover,.row.selected{background:#17253a}.primary{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px}.secondary{margin-top:4px;color:#8496ad;font:11px system-ui;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row mark,.detail mark{background:#ff405229;color:#ff6675;border:1px solid #ff405266;border-radius:3px;padding:0 2px;font-size:1.08em;font-weight:900}.badge{display:inline-block;border-radius:4px;padding:1px 5px;margin-right:5px;background:#25415b;color:#83dcff;font-size:10px}.bad{background:#542638;color:#ff9aac}.detail{overflow:auto;padding:14px}.detail-head{display:flex;align-items:center;gap:10px;margin:0 0 10px}.detail-head h3{margin:0;min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#8ee5ff;font:700 14px system-ui}.copy-detail{flex:none;padding:5px 9px}.detail h4{margin:0 0 8px;color:#ff9aa4;font:700 12px system-ui}.detail pre{white-space:pre-wrap;word-break:break-word;margin:0;color:#ced9e8;font:12px/1.55 ui-monospace,monospace}.match-box{margin:0 0 14px;padding:10px;border:1px solid #52303a;border-radius:8px;background:#25151b}.match-item+.match-item{margin-top:8px}.match-label{margin-bottom:3px;color:#d5939b;font:700 10px system-ui}.raw-detail{padding-top:12px;border-top:1px solid #263249}.empty{padding:24px;color:#73839a;text-align:center;font:13px system-ui}.foot{display:flex;align-items:center;flex-wrap:wrap;gap:9px;padding:8px 11px;border-top:1px solid #263249;color:#7f91a8;font:11px system-ui}.foot label{display:flex;align-items:center;gap:4px}.foot input{width:75px;padding:4px 6px}.foot input[type=checkbox]{width:auto;padding:0;accent-color:#2b9ec1}.window-options{padding-left:9px;border-left:1px solid #34425b}.launcher{display:block;width:76px;height:64px;margin:0 0 6px auto;padding:0;border:0;background:transparent;filter:drop-shadow(0 8px 18px #0008);cursor:pointer;transition:transform .16s ease,filter .16s ease}.launcher:hover{transform:scale(1.05);filter:drop-shadow(0 10px 22px #0009)}.launcher:focus-visible{outline:2px solid #6edcff;outline-offset:2px;border-radius:18px}.launcher img{display:block;width:100%;height:100%;object-fit:contain}@media(max-width:650px){.body{grid-template-columns:1fr}.detail{display:none}.search{width:120px}.panel{height:calc(100vh - 20px);width:calc(100vw - 20px)}}
      </style>
      <button class="launcher" type="button" aria-label="打开 Monitor" aria-expanded="false" title="打开 Monitor v${VERSION}"><img src="${ICON_DATA_URL}" alt=""></button>
      <section class="panel">
        <header class="head"><div class="title">Monitor <small>v${VERSION}</small></div><div class="stats"></div><div class="controls"><button class="btn pause">暂停</button><button class="btn export">导出</button><button class="btn clear">清空记录</button><button class="btn close">关闭</button></div></header>
        <nav class="tabs"><button class="btn tab active" data-tab="network">网络</button><button class="btn tab" data-tab="storage">Storage</button><button class="btn tab" data-tab="globals">Window</button><button class="btn tab" data-tab="timeline">变化</button><input class="search" placeholder="全文搜索名称、路径或内容"></nav>
        <main class="body"><div class="list"></div><article class="detail"><div class="empty">选择一条记录查看详情</div></article></main>
        <footer class="foot"><label>请求条数 <input class="max-entries" type="number" min="10" max="2000"></label><label>响应上限 KB <input class="max-body" type="number" min="4" max="2048"></label><label>网络文本上限 MB <input class="max-total" type="number" min="1" max="100"></label><label class="window-options"><input class="show-functions" type="checkbox">显示函数</label><label><input class="show-initial-globals" type="checkbox">显示初始全局</label></footer>
      </section>`;
    document.documentElement.appendChild(host);
    bindUi();
    render();
  }

  function bindUi() {
    const $ = (selector) => shadow.querySelector(selector);
    $('.launcher').addEventListener('click', () => {
      const open = $('.panel').classList.toggle('open');
      $('.launcher').setAttribute('aria-expanded', String(open));
      $('.launcher').setAttribute('aria-label', open ? '关闭 Monitor' : '打开 Monitor');
      $('.launcher').title = `${open ? '关闭' : '打开'} Monitor v${VERSION}`;
    });
    $('.close').addEventListener('click', () => {
      $('.panel').classList.remove('open');
      $('.launcher').setAttribute('aria-expanded', 'false');
      $('.launcher').setAttribute('aria-label', '打开 Monitor');
      $('.launcher').title = `打开 Monitor v${VERSION}`;
    });
    $('.pause').addEventListener('click', () => {
      state.paused = !state.paused;
      $('.pause').textContent = state.paused ? '继续' : '暂停';
      host.classList.toggle('paused', state.paused);
      render();
    });
    $('.clear').addEventListener('click', () => {
      state.network = [];
      state.networkTextBytes = 0;
      state.timeline = [];
      state.selected = null;
      render();
    });
    $('.export').addEventListener('click', exportData);
    $('.search').addEventListener('input', (event) => { state.filter = event.target.value.toLowerCase(); render(); });
    $('.show-functions').addEventListener('change', (event) => {
      state.showGlobalFunctions = event.target.checked;
      state.selected = null;
      render();
    });
    $('.show-initial-globals').addEventListener('change', (event) => {
      state.showInitialGlobals = event.target.checked;
      state.selected = null;
      render();
    });
    shadow.querySelectorAll('.tab').forEach((tab) => tab.addEventListener('click', () => {
      state.activeTab = tab.dataset.tab;
      state.selected = null;
      shadow.querySelectorAll('.tab').forEach((item) => item.classList.toggle('active', item === tab));
      render();
    }));
    const inputs = {
      '.max-entries': ['maxNetworkEntries', 1],
      '.max-body': ['maxResponseBytes', 1024],
      '.max-total': ['maxNetworkTextBytes', 1024 * 1024],
    };
    for (const [selector, [key, multiplier]] of Object.entries(inputs)) {
      const input = $(selector);
      input.value = Math.round(config[key] / multiplier);
      input.addEventListener('change', () => {
        const min = Number(input.min) || 1;
        const max = Number(input.max) || Number.MAX_SAFE_INTEGER;
        input.value = Math.min(max, Math.max(min, Number(input.value) || min));
        config[key] = Number(input.value) * multiplier;
        enforceNetworkLimits();
        render();
      });
    }
    $('.list').addEventListener('click', (event) => {
      const row = event.target.closest('[data-id]');
      if (!row) return;
      state.selected = row.dataset.id;
      render();
    });
    $('.detail').addEventListener('click', async (event) => {
      const button = event.target.closest('.copy-detail');
      if (!button) return;
      const selected = currentItems().find((item) => String(item.id) === String(state.selected));
      if (!selected) return;
      const copied = await copyToClipboard(buildDetailCopyText(selected));
      button.textContent = copied ? '已复制' : '复制失败';
      setTimeout(() => { if (button.isConnected) button.textContent = '复制详情'; }, 1400);
    });
  }

  function currentItems() {
    if (state.activeTab === 'network') return state.network;
    if (state.activeTab === 'storage') return [...state.storage.values()].sort((a, b) => a.kind.localeCompare(b.kind) || a.key.localeCompare(b.key));
    if (state.activeTab === 'globals') {
      return [...state.globals.values()]
        .filter((item) => state.showGlobalFunctions || item.type !== 'Function')
        .filter((item) => state.showInitialGlobals || !item.initial)
        .sort((a, b) => a.key.localeCompare(b.key));
    }
    return state.timeline;
  }

  function itemSearchText(item) {
    return Object.values(item).filter((value) => ['string', 'number', 'boolean'].includes(typeof value)).join(' ').toLowerCase();
  }

  function render() {
    if (!state.uiReady) return;
    const list = shadow.querySelector('.list');
    const items = currentItems().filter((item) => !state.filter || itemSearchText(item).includes(state.filter));
    const visibleGlobalCount = [...state.globals.values()]
      .filter((item) => state.showGlobalFunctions || item.type !== 'Function')
      .filter((item) => state.showInitialGlobals || !item.initial).length;
    shadow.querySelector('.stats').textContent = `网络 ${state.network.length}/${config.maxNetworkEntries} · Storage ${state.storage.size} · Window ${visibleGlobalCount}/${state.globals.size} · 约 ${(state.networkTextBytes / 1024 / 1024).toFixed(2)} MB`;
    if (!items.length) {
      list.innerHTML = '<div class="empty">暂无记录</div>';
    } else {
      list.innerHTML = items.map((item) => renderRow(item)).join('');
    }
    const selected = items.find((item) => String(item.id) === String(state.selected));
    shadow.querySelector('.detail').innerHTML = selected
      ? renderDetail(selected)
      : '<div class="empty">选择一条记录查看详情</div>';
  }

  function renderRow(item) {
    let primary;
    let secondary;
    let badge;
    if (state.activeTab === 'network') {
      primary = `${item.method} ${item.url}`;
      secondary = `${item.status || 'ERR'} · ${item.durationMs}ms · ${item.contentType || 'unknown'}${item.truncated ? ' · 已截断' : ''}`;
      badge = `<span class="badge ${item.ok ? '' : 'bad'}">${escapeHtml(item.type)}</span>`;
    } else if (state.activeTab === 'storage') {
      primary = item.key; secondary = truncate(item.value, 100).replace(/\n/g, ' '); badge = `<span class="badge">${escapeHtml(item.kind)}</span>`;
    } else if (state.activeTab === 'globals') {
      primary = item.key; secondary = truncate(item.preview, 100).replace(/\n/g, ' '); badge = `<span class="badge">${escapeHtml(item.type)}</span>`;
    } else {
      primary = item.key; secondary = `${item.time} · ${item.detail || ''}`; badge = `<span class="badge">${escapeHtml(`${item.source}:${item.action}`)}</span>`;
    }
    secondary = matchingSnippet(item, secondary);
    return `<div class="row ${String(item.id) === String(state.selected) ? 'selected' : ''}" data-id="${escapeHtml(item.id)}"><div class="primary">${badge}${highlightText(primary)}</div><div class="secondary">${highlightText(secondary)}</div></div>`;
  }

  function detailTitle(item) {
    return item.url || item.key || item.id;
  }

  function detailValue(item) {
    if (state.activeTab !== 'globals') return item;
    const { fingerprint, searchText, searchEvicted, ...visible } = item;
    return visible;
  }

  function renderDetail(item) {
    const details = matchingDetails(item);
    const matches = details.length
      ? `<section class="match-box"><h4>匹配内容（${details.length}）</h4>${details.map((match) => `<div class="match-item"><div class="match-label">${escapeHtml(match.label)}</div><pre>${highlightText(match.text)}</pre></div>`).join('')}</section>`
      : '';
    const json = JSON.stringify(detailValue(item), null, 2);
    return `<div class="detail-head"><h3>${highlightText(detailTitle(item))}</h3><button class="btn copy-detail" type="button">复制详情</button></div>${matches}<pre class="raw-detail">${highlightText(json)}</pre>`;
  }

  function buildDetailCopyText(item) {
    const lines = [`标题：${detailTitle(item)}`];
    const details = matchingDetails(item);
    if (details.length) {
      lines.push('', `匹配内容（${details.length}）`);
      for (const match of details) lines.push(`[${match.label}] ${match.text}`);
    }
    lines.push('', '详情', JSON.stringify(detailValue(item), null, 2));
    return lines.join('\n');
  }

  async function copyToClipboard(text) {
    try {
      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        await navigator.clipboard.writeText(text);
        return true;
      }
    } catch (_) {}
    try {
      const textarea = document.createElement('textarea');
      textarea.value = text;
      textarea.setAttribute('readonly', '');
      textarea.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0';
      document.documentElement.appendChild(textarea);
      textarea.focus();
      textarea.select();
      const copied = document.execCommand('copy');
      textarea.remove();
      return copied;
    } catch (_) {
      return false;
    }
  }

  function scheduleRender() {
    if (!state.uiReady || state.renderQueued) return;
    state.renderQueued = true;
    requestAnimationFrame(() => { state.renderQueued = false; render(); });
  }

  function exportData() {
    const data = {
      exportedAt: nowIso(),
      limits: { ...config },
      note: 'Values are previews and may be truncated by configured limits.',
      network: state.network,
      storage: [...state.storage.values()],
      globals: [...state.globals.values()].map(({ fingerprint, searchText, searchEvicted, ...item }) => item),
      timeline: state.timeline,
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `monitor-${Date.now()}.json`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }

  function startScanner() {
    scanStorage(true);
    scanGlobals(true);
    setInterval(() => {
      if (state.paused) return;
      scanStorage(false);
      scanGlobals(false);
    }, config.scanIntervalMs);
  }

  installFetchHook();
  installXhrHook();
  installStorageHook();
  startScanner();
  if (document.documentElement) createUi();
  else new MutationObserver((_records, observer) => {
    if (!document.documentElement) return;
    observer.disconnect();
    createUi();
  }).observe(document, { childList: true, subtree: true });
})();
